const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体' },
      { kind: 'text', payload: '静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v、g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var W = Number(input.viewport.widthDu) || 480;
    var H = Number(input.viewport.heightDu) || 360;
    var cx = W * 0.5;
    var cy = H * 0.30;
    var r = Math.max(12, Math.min(W, H) * 0.075);
    var topY = cy + r + 14;
    var bottomY = Math.min(H * 0.80, topY + Math.min(H * 0.30, 120));
    if (bottomY < topY + 24) { bottomY = topY + 24; }
    var vx = cx + r * 1.15;
    var gx = cx - r * 1.15;
    var midY = (topY + bottomY) / 2;
    var gArrow = visualSdk.arrow(gx, topY, gx, bottomY, {});
    var vArrow = visualSdk.arrow(vx, topY, vx, bottomY, {});
    var ballOutline = visualSdk.circle(cx, cy, r);
    var ballFill = visualSdk.circle(cx, cy, Math.max(4, r - 3));
    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ballOutline', commands: ballOutline },
        { id: 'ballFill', commands: ballFill },
        { id: 'gArrow', commands: gArrow },
        { id: 'vArrow', commands: vArrow }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'ballOutline', fill: '#26354a', stroke: { width: 2 } },
        { type: 'path', pathId: 'ballFill', fill: '#dbe7f5', stroke: { width: 1 } },
        { type: 'path', pathId: 'gArrow', fill: '#26354a', stroke: { width: 2 } },
        { type: 'path', pathId: 'vArrow', fill: '#26354a', stroke: { width: 2 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.5, y: H * 0.06 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx, y: cy - r - 12 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: vx + 10, y: midY }, hAlign: 'left', vAlign: 'middle', color: '#26354a' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: gx - 10, y: midY }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: W * 0.5, y: H * 0.92 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' }
      ] }
    };
  }
};
